const ONE = {'種':'jenis','個':'buah','條':'ekor','隻':'ekor','次':'kali','件':'buah','顆':'butir','低':'Rendah','中':'Sedang','高':'Tinggi','你':'Kamu','再':'Lagi','天':'hari','秒':'dtk'};
